steps.solution:
function positionOf(playlist, song) {
  for (let i = 0; i < playlist.length; i++) {
    if (playlist[i] === song) return i
  }
  return -1
}

console.log(positionOf(['Intro', 'Echo'], 'Echo')) // 1
